diff --git a/src/runner/dependency.rs b/src/runner/dependency.rs
index 872fd69..aba45a0 100644
--- a/src/runner/dependency.rs
+++ b/src/runner/dependency.rs
@@ -688,4 +688,351 @@ mod tests {

         assert!(skipped.is_empty());
     }
+
+    // --- Circular reference tests for recursive resolution ---
+
+    #[test]
+    fn transitive_dependents_handles_two_node_cycle() {
+        // A depends on B, B depends on A — transitive_dependents must not infinite loop
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        // "a" depends on "b" so "b" has "a" as a dependent, and vice versa
+        let deps_b = graph.transitive_dependents("b");
+        assert!(deps_b.contains("a"));
+    }
+
+    #[test]
+    fn transitive_dependents_handles_three_node_cycle() {
+        // A→B→C→A cycle — must terminate
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        assert!(deps.contains("c"));
+    }
+
+    #[test]
+    fn transitive_dependents_handles_self_cycle() {
+        // A depends on itself — must terminate
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+

